#include <stdio.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdlib.h>
#include "memory_map.h"
#include "core_v5.h"

#if __riscv_xlen == 64
	#define ROTATE_LEN 64
#else
	#define ROTATE_LEN 32
#endif

#ifndef NDS_MIN_ILM_SIZE
	#define NDS_MIN_ILM_SIZE 0x6000
#endif


typedef struct {
	long *base;
	long size;
	const char *name;
	const char *asm_label_prefix;
} memory_config_t;

long micm_cfg;
long milmb;
long ilm_size;
long mdcm_cfg;
long dlm_size;
long mdlmb;

void setup_ilm() {
	micm_cfg = read_csr(NDS_MICM_CFG);

	ilm_size = (0x200 << ((micm_cfg >> 15) & 0x1f)) / sizeof(long);
	if (ilm_size < (NDS_MIN_ILM_SIZE / sizeof(long))) {
		printf("Error: ILM size should be >= 24 KiB to run this test.\n");
		exit(1);
	}

	set_csr(NDS_MILMB, 0x1);
	milmb = read_csr(NDS_MILMB);

	if (((micm_cfg >> 21) & 0x3) != 0) {
		milmb |= 0x4;
		write_csr(NDS_MILMB, milmb);
	}
}

void setup_dlm() {
	mdcm_cfg = read_csr(NDS_MDCM_CFG);

	if (((mdcm_cfg >> 15) & 0x1f) != 0) {
		dlm_size = (0x200 << ((mdcm_cfg >> 15) & 0x1f)) / sizeof(long);
	} else {
		printf("Error: DLM size should be > 0 KiB to run this test.\n");
		exit(1);
	}

	set_csr(NDS_MDLMB, 0x1);
	mdlmb = read_csr(NDS_MDLMB);

	if (((mdcm_cfg >> 21) & 0x3) != 0) {
		mdlmb |= 0x4;
		write_csr(NDS_MDLMB, mdlmb);
	}
}

void setup() {
	setup_ilm();
	setup_dlm();
}

long rotr(long num) {
	return (num >> 1) | (num << (ROTATE_LEN - 1));
}

void wait_for_transfer() {
	for (int i = 0; i < 32; i++) {
		asm volatile("nop");
	}
}

void print_initial_memory_data(const memory_config_t *mem_config) {
	uintptr_t start = (uintptr_t)mem_config->base;
	uintptr_t end = start + 32;

	printf("First read - Initial %s data:\n", mem_config->name);
	for (uintptr_t addr = start; addr < end; addr += 4) {
		unsigned int data = *(unsigned int *)(uintptr_t)addr;
		printf("addr = %" PRIxPTR ", data = %x\n", addr, data);
	}
}

void generic_memory_test_pattern1(const memory_config_t *mem_config, long data1) {
	long offset, golden, test;
	char write_label[32], read_label[32];

	snprintf(write_label, sizeof(write_label), "%s_write_1:", mem_config->asm_label_prefix);
	snprintf(read_label, sizeof(read_label), "%s_read_1:", mem_config->asm_label_prefix);

	asm volatile ("# Pattern 1 write");
	test = data1;
	for (offset = 1; offset < mem_config->size; offset = offset << 2) {
		test = rotr(test);
		*(mem_config->base + offset) = test;
	}

	asm volatile ("# Pattern 1 read");
	golden = data1;
	for (offset = 1; offset < mem_config->size; offset = offset << 2) {
		golden = rotr(golden);
		test = *(mem_config->base + offset);
		printf("%s Read 1 - offset: %ld, expected: 0x%lx, actual: 0x%lx\n", 
		       mem_config->name, offset, golden, test);
		if (golden != test) {
			printf("%s Test failed at offset %ld\n", mem_config->name, offset);
			exit(1);
		}
	}
}

void generic_memory_test_pattern2(const memory_config_t *mem_config, long data2) {
	long offset, golden, test;
	char write_label[32], read_label[32];

	snprintf(write_label, sizeof(write_label), "%s_write_2:", mem_config->asm_label_prefix);
	snprintf(read_label, sizeof(read_label), "%s_read_2:", mem_config->asm_label_prefix);

	asm volatile ("# Pattern 2 write");
	test = data2;
	for (offset = (mem_config->size >> 1); offset > 0; offset = offset >> 2) {
		test = rotr(test);
		*(mem_config->base + offset) = test;
	}

	asm volatile ("# Pattern 2 read");
	golden = data2;
	for (offset = (mem_config->size >> 1); offset > 0; offset = offset >> 2) {
		golden = rotr(golden);
		test = *(mem_config->base + offset);
		printf("%s Read 2 - offset: %ld, expected: 0x%lx, actual: 0x%lx\n", 
		       mem_config->name, offset, golden, test);
		if (golden != test) {
			printf("%s Test failed at offset %ld\n", mem_config->name, offset);
			exit(1);
		}
	}
}

void run_memory_tests(const memory_config_t *mem_config, long data1, long data2) {
	printf("=== %s Testing ===\n", mem_config->name);
	printf("%s Base address: 0x%lx\n", mem_config->name, (unsigned long)mem_config->base);
	printf("%s Size: %ld words\n", mem_config->name, mem_config->size);

	print_initial_memory_data(mem_config);

	printf("Running %s test pattern 1...\n", mem_config->name);
	generic_memory_test_pattern1(mem_config, data1);

	printf("Running %s test pattern 2...\n", mem_config->name);
	generic_memory_test_pattern2(mem_config, data2);

	printf("%s tests passed!\n\n", mem_config->name);
}

int main(int argc, char** argv) {
	const long ILM_DATA1 = 0x5a5a5a5a;
	const long ILM_DATA2 = 0x12345678;
	const long DLM_DATA1 = 0xa5a5a5a5;
	const long DLM_DATA2 = 0x87654321;

	printf("Starting local memory test...\n");

	setup();

	memory_config_t ilm_config = {
		.base = (long*)(((milmb >> 10) << 10)),
		.size = ilm_size,
		.name = "ILM",
		.asm_label_prefix = "ilm"
	};

	memory_config_t dlm_config = {
		.base = (long*)(((mdlmb >> 10) << 10)),
		.size = dlm_size,
		.name = "DLM",
		.asm_label_prefix = "dlm"
	};

	// trigger custom_master to write ILM via slave port
	SIM_CONTROL_REG = TEST_ILM;
	wait_for_transfer();
	run_memory_tests(&ilm_config, ILM_DATA1, ILM_DATA2);

	// trigger custom_master to write DLM via slave port
	SIM_CONTROL_REG = TEST_DLM;
	wait_for_transfer();
	run_memory_tests(&dlm_config, DLM_DATA1, DLM_DATA2);

	printf("All local memory tests passed!\n");
	return 0;
}

