#pragma once

#include "memory_map.h"

#include <spdlog/spdlog.h>
#include <systemc>
#include <tlm>
#include <tlm_utils/simple_initiator_socket.h>

enum class SubPortTest
{
  TEST_ILM,
  TEST_DLM,
  TEST_HVM,
};

extern SubPortTest subport_test;
extern sc_core::sc_semaphore custom_master_sem;
extern unsigned char test_data[16];

template<std::size_t BusWidth = 32>
struct CustomMaster : sc_core::sc_module
{
  unsigned long long hvm_base = 0x90000000;
  unsigned long long ilm_base = 0xA0000000;
  unsigned long long dlm_base = 0xA0200000;

  sc_core::sc_in<bool> clk{"clk"};

  tlm_utils::simple_initiator_socket<CustomMaster, BusWidth> socket{"isck"};

  SC_CTOR(CustomMaster) { SC_THREAD(custom_thread); }

  void custom_thread()
  {
    auto ext = new axi::axi4_extension;
    tlm::tlm_command cmd =
      static_cast<tlm::tlm_command>(tlm::TLM_WRITE_COMMAND);

    // prepare a reused payload
    tlm::tlm_generic_payload* trans = new tlm::tlm_generic_payload;
    trans->set_command(cmd);
    trans->set_data_length(1);
    trans->set_streaming_width(1); // = data_length to indicate no streaming
    trans->set_byte_enable_ptr(0); // 0 indicates unused
    trans->set_dmi_allowed(false); // Mandatory initial value
    trans->set_extension(ext);
    // Mandatory initial value
    trans->set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);

    for (int i = 0; i < 100; i++) {
      wait(this->clk.posedge_event());
    }

    while (1) {
      custom_master_sem.wait();

      unsigned long long base;

      switch (subport_test) {
      case SubPortTest::TEST_ILM:
        base = ilm_base;
        break;
      case SubPortTest::TEST_DLM:
        base = dlm_base;
        break;
      case SubPortTest::TEST_HVM:
        base = hvm_base;
        break;
      default:
        continue;
        break;
      }

      unsigned long long end = base + sizeof(test_data);

      for (unsigned long long addr = base, i = 0; addr < end; addr += 1, i++) {

        trans->set_address(addr);
        trans->set_data_ptr(test_data + i);

        sc_core::sc_time delay = sc_core::SC_ZERO_TIME;
        this->socket->b_transport(*trans, delay);

        // Initiator obliged to check response status
        if (trans->is_response_error())
          SC_REPORT_ERROR("TLM-2", "Response error from b_transport");

        auto ts = sc_core::sc_time_stamp().to_double();
        spdlog::debug("trans = {}, {:#x} , data = {:#x} at time {}",
                      (cmd ? 'W' : 'R'), addr, test_data[i], ts);

        wait(this->clk.posedge_event());
      }
    }
  }
};

