199	      handle_htif_32bit_high_write(buf);
200	    } else if (offset == INT_TRIGGER_OFFSET && len == 4) {
201	      auto val = unpack<uint32_t>(buf);
202	      spdlog::debug("sim_control: int_trigger = {:#x}", val);
