284	  void execute_htif_syscall()
285	  {
286	    command_t cmd(partial_htif_command);
287	    if (cmd.device() != 0 || cmd.cmd() != 0) {
288	      spdlog::warn("sim_control: unknown device: #{}", cmd.device());
289	      return;
290	    }
291	    dispatch(cmd);
292	    partial_htif_command = 0;
293	    htif_parts_received = 0;
294	  }
295	
296	  void handle_htif_64bit_write(const std::span<uint8_t>& buf)
297	  {
298	    command_t cmd(unpack<uint64_t>(buf));
299	    if (cmd.device() == 0 && cmd.cmd() == 0)
300	      dispatch(cmd);
301	    else
302	      spdlog::warn("sim_control: unknown device: #{}", cmd.device());
303	  }
304	
305	  void handle_htif_32bit_low_write(const std::span<uint8_t>& buf)
306	  {
307	    partial_htif_command |= unpack<uint32_t>(buf);
308	    if (++htif_parts_received == HTIF_32BIT_PARTS)
309	      execute_htif_syscall();
310	  }
311	
312	  void handle_htif_32bit_high_write(const std::span<uint8_t>& buf)
313	  {
314	    partial_htif_command |= static_cast<uint64_t>(unpack<uint32_t>(buf)) << 32;
315	    if (++htif_parts_received == HTIF_32BIT_PARTS)
316	      execute_htif_syscall();
317	  }
318	
319	  void dispatch(command_t cmd)
320	  {
321	    uint64_t syscall_args[MAGIC_MEM_SIZE];
322	    auto addr_offset = cmd.payload() - data_region.region.base_address;
323	    auto src = data_region.data.begin() + addr_offset;
324	
325	    std::copy(src, src + sizeof(syscall_args),
326	              reinterpret_cast<uint8_t*>(syscall_args));
327	
328	    spdlog::debug("sim_control: args: {:#x}, {:#x}, {:#x}, "
329	                  "{:#x}, {:#x}, {:#x}, {:#x}",
330	                  syscall_args[0], syscall_args[1], syscall_args[2],
331	                  syscall_args[3], syscall_args[4], syscall_args[5],
332	                  syscall_args[6]);
333	
334	    auto syscall_num = syscall_args[0];
335	    if (syscall_num >= SYSCALL_TABLE_SIZE || !sim_syscall_table[syscall_num]) {
336	      spdlog::critical("sim_control: invalid syscall number {}", syscall_num);
337	      syscall_args[0] = static_cast<uint64_t>(-1);
338	    } else {
339	      syscall_args[0] = (this->*sim_syscall_table[syscall_num])(
340	        syscall_args[1], syscall_args[2], syscall_args[3], syscall_args[4],
341	        syscall_args[5], syscall_args[6], syscall_args[7]);
342	    }
343	
344	    std::copy(reinterpret_cast<uint8_t*>(syscall_args),
345	              reinterpret_cast<uint8_t*>(syscall_args) + sizeof(syscall_args),
346	              src);
347	  }
348	};
