void load_lm(const std::string& path, MEM_TYPE type)
{
  switch (type) {
  case MEM_TYPE::ILM:
    if constexpr (requires { cpu.set_ilm({}); }) {
      read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
    } else {
      throw std::runtime_error(
        "CPU does not support ILM - cannot load ILM ROM image");
    }
    break;

  case MEM_TYPE::DLM:
    if constexpr (requires { cpu.set_dlm({}); }) {
      read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
    } else {
      throw std::runtime_error(
        "CPU does not support DLM - cannot load DLM ROM image");
    }
    break;

  default:
    throw std::runtime_error("Unknown memory type");
  }
}

// Save a snapshot (memory + CPU/DM register dump) when the core hits WFI
// with a snapshot directory configured. Returns true so run() can end with
// exit code 0; the decision to return stays in run() for consistency with
// the other exit conditions.
void save_snapshot_on_wfi()
{
  const auto patched_pc = pending_stop_pc_;
  if (stop_pc_patch_) {
    stop_pc_patch_->uninstall();
    stop_pc_patch_.reset();
  }

  ::save_memory(platform, snapshot_dir);

  if (save_signal)
    ::save_context(cpu, snapshot_dir);
  else {
    // dump GPR,CSR,... via DM. If we exited on a --stop-pc patched WFI,
    // force the dumped pc to be the patch address so the next resume
    // restarts there exactly.
    platform.dmi_controller.dump_registers(
      save_list_path_, snapshot_dir + "/regs.dm", patched_pc);
    int waited = 0;
    for (waited = 0; !platform.dmi_controller.done(); waited++)
      sc_core::sc_start(platform.clk.period());
    spdlog::debug("waited {} cycles for dumping registers", waited);
    dm_waited_cycles_ += waited;
  }
  spdlog::info("snapshot has been saved to {}", snapshot_dir);
}

