  void set_dlm(const std::vector<uint8_t>& data)
  {
    if (data.size() > SIZE) {
      throw std::runtime_error("DLM data size (" + std::to_string(data.size())
                               + " bytes) exceeds DLM capacity ("
                               + std::to_string(SIZE) + " bytes)");
